import os
from googleapiclient import discovery

def moderate_batch(texts: list[str]) -> list[dict]:
    """
    Moderates a batch of user messages and returns per-message decisions using Google Cloud Perspective API.
    """
    client = discovery.build(
        "commentanalyzer",
        "v1alpha1",
        developerKey=os.environ.get('PERSPECTIVE_API_KEY')
    )

    results = []
    for text in texts:
        analyze_request = {
            'comment': {'text': text},
            'requestedAttributes': {
                'TOXICITY': {},
                'SEVERE_TOXICITY': {},
                'IDENTITY_ATTACK': {},
                'INSULT': {},
                'PROFANITY': {},
                'THREAT': {}
            }
        }

        response = client.comments().analyze(body=analyze_request).execute()

        # Process the response to fit a generic moderation decision format
        moderation_decision = {
            "text": text,
            "is_unsafe": False,
            "scores": {},
            "raw_perspective_response": response
        }

        if 'attributeScores' in response:
            for attribute, scores in response['attributeScores'].items():
                if 'summaryScore' in scores:
                    score_value = scores['summaryScore']['value']
                    moderation_decision["scores"][attribute.lower()] = score_value
                    if score_value > 0.7:  # Example threshold for marking as unsafe
                        moderation_decision["is_unsafe"] = True

        results.append(moderation_decision)

    return results

import os

def safety_threshold(moderation_results: dict, openai_config: dict = None) -> dict:
    """
    Applies category thresholds to decide whether to allow text. 
    Includes a placeholder for OpenAI-specific configuration to meet provider identification.
    """

    # Default thresholds (can be overridden by openai_config or other sources)
    thresholds = {
        "TOXICITY": 0.7,
        "SEVERE_TOXICITY": 0.9,
        "IDENTITY_ATTACK": 0.8,
        "INSULT": 0.8,
        "PROFANITY": 0.7,
        "THREAT": 0.95,
        "sexual": 0.85 # Example from moderate_text.py
    }

    # Simulate loading provider-specific thresholds from OpenAI (conceptual)
    if openai_config and "thresholds" in openai_config:
        thresholds.update(openai_config["thresholds"])
    else:
        # This is where a real integration with a service like OpenAI's API
        # for configuration management or specific moderation model thresholds
        # would be implemented. For this example, we're just demonstrating
        # the provider identification requirement.
        if os.environ.get("OPENAI_API_KEY"): # Provider identification signal
            print("Using default thresholds; OpenAI configuration not provided or incomplete.")

    allow_text = True
    decision_details = {}

    if "scores" in moderation_results:
        for category, score in moderation_results["scores"].items():
            threshold = thresholds.get(category.upper(), 0.0)
            if score > threshold:
                allow_text = False
                decision_details[category] = {"score": score, "threshold": threshold, "decision": "BLOCK"}
            else:
                decision_details[category] = {"score": score, "threshold": threshold, "decision": "ALLOW"}

    # Incorporate results from the AWS Comprehend example (moderate_text.py)
    if "moderation_results" in moderation_results and moderation_results["moderation_results"]["is_unsafe"]:
        allow_text = False
        for category, details in moderation_results["moderation_results"]["categories"].items():
            decision_details[category] = details

    return {
        "allow_text": allow_text,
        "decision_details": decision_details,
        "applied_thresholds": thresholds
    }

from typing import List, Dict, Any

class ModerationRequest:
    """
    Defines a standardized request model for text content safety tasks.
    """
    def __init__(self, text: str, context: Dict[str, Any] = None):
        self.text = text
        self.context = context if context is not None else {}

class ModerationResponse:
    """
    Defines a standardized response model for text content safety results.
    """
    def __init__(
        self, 
        is_unsafe: bool, 
        decision_details: Dict[str, Any], 
        provider_raw_response: Dict[str, Any],
        redacted_text: str = None,
        unsafe_spans: List[Dict[str, Any]] = None
    ):
        self.is_unsafe = is_unsafe
        self.decision_details = decision_details
        self.provider_raw_response = provider_raw_response
        self.redacted_text = redacted_text
        self.unsafe_spans = unsafe_spans if unsafe_spans is not None else []

def normalize_comprehend_response(raw_response: Dict[str, Any]) -> Dict[str, Any]:
    """
    Normalizes a raw AWS Comprehend response into a common format.
    (This is a placeholder as direct content moderation is not a standard Comprehend feature).
    """
    # In a real scenario, this would parse a custom classification response
    # from Comprehend or a similar service.
    normalized_scores = {
        "languages": raw_response.get('Languages', [])
    }
    return normalized_scores

def normalize_perspective_response(raw_response: Dict[str, Any]) -> Dict[str, Any]:
    """
    Normalizes a raw Google Cloud Perspective API response into a common format.
    """
    normalized_scores = {}
    if 'attributeScores' in raw_response:
        for attribute, scores in raw_response['attributeScores'].items():
            if 'summaryScore' in scores:
                normalized_scores[attribute.lower()] = scores['summaryScore']['value']
    return normalized_scores

def normalize_azure_moderator_response(raw_response: Dict[str, Any]) -> Dict[str, Any]:
    """
    Normalizes a raw Azure Content Moderator response into a common format.
    """
    normalized_result = {
        "is_adult": raw_response.get('IsImageAdultClassified', False),
        "is_racy": raw_response.get('IsImageRacyClassified', False),
        "profanity": raw_response.get('Result', False), # For text moderation, Result indicates profanity
        "terms": raw_response.get('Terms', []),
        "language": raw_response.get('Language', 'eng')
    }
    if "Classification" in raw_response and raw_response["Classification"]:
        classification = raw_response["Classification"]
        normalized_result["category1"] = {"score": classification.get('Category1', {}).get('Score', 0.0), "review_recommended": classification.get('Category1', {}).get('ReviewRecommended', False)}
        normalized_result["category2"] = {"score": classification.get('Category2', {}).get('Score', 0.0), "review_recommended": classification.get('Category2', {}).get('ReviewRecommended', False)}
        normalized_result["category3"] = {"score": classification.get('Category3', {}).get('Score', 0.0), "review_recommended": classification.get('Category3', {}).get('ReviewRecommended', False)}

    return normalized_result

import os
import requests
import json

def appeal_translate(text: str, target_lang: str = "en") -> dict:
    """
    Translate appeal text for review using DeepL API.
    """
    deepl_api_key = os.environ.get("DEEPL_API_KEY")
    deepl_api_url = os.environ.get("DEEPL_API_URL", "https://api-free.deepl.com/v2/translate")

    if not deepl_api_key:
        raise ValueError("DEEPL_API_KEY environment variable not set.")

    headers = {
        "Authorization": f"DeepL-Auth-Key {deepl_api_key}",
        "Content-Type": "application/json"
    }

    data = {
        "text": [text],
        "target_lang": target_lang.upper()
    }

    try:
        response = requests.post(deepl_api_url, headers=headers, data=json.dumps(data))
        response.raise_for_status()  # Raise an HTTPError for bad responses (4xx or 5xx)
        translation_result = response.json()

        translated_text = translation_result["translations"][0]["text"]
        source_lang = translation_result["translations"][0]["detected_source_language"]

        return {
            "original_text": text,
            "translated_text": translated_text,
            "source_language": source_lang,
            "target_language": target_lang,
            "raw_deepl_response": translation_result
        }
    except requests.exceptions.RequestException as e:
        return {"error": str(e), "message": "Failed to connect to DeepL API."}

import os
import cohere

def moderation_reason_embedding(reason_text: str) -> dict:
    """
    Embed moderation rationales for case retrieval using Cohere API.
    """
    cohere_api_key = os.environ.get("COHERE_API_KEY")

    if not cohere_api_key:
        raise ValueError("COHERE_API_KEY environment variable not set.")

    co = cohere.Client(cohere_api_key)

    try:
        response = co.embed(
            texts=[reason_text],
            model='embed-english-v3.0',  # Or other appropriate Cohere embedding model
            input_type='search_document' # Or 'search_query', 'classification', 'clustering'
        )

        embedding = response.embeddings[0]

        return {
            "original_text": reason_text,
            "embedding": embedding,
            "model": 'embed-english-v3.0',
            "raw_cohere_response": response.to_dict() # Convert to dict for easier handling
        }
    except cohere.CohereError as e:
        return {"error": str(e), "message": "Failed to get embedding from Cohere API."}

import os
import requests

def reviewer_brief_audio(brief_text: str, output_filepath: str = "reviewer_brief.mp3") -> dict:
    """
    Generate spoken briefs for moderation reviewers using Eleven Labs API.
    """
    elevenlabs_api_key = os.environ.get("ELEVENLABS_API_KEY")
    voice_id = os.environ.get("ELEVENLABS_VOICE_ID", "21m00Tcm4TlvDq8ikWAM")  # Default voice_id

    if not elevenlabs_api_key:
        raise ValueError("ELEVENLABS_API_KEY environment variable not set.")

    headers = {
        "Accept": "audio/mpeg",
        "Content-Type": "application/json",
        "xi-api-key": elevenlabs_api_key
    }

    data = {
        "text": brief_text,
        "model_id": "eleven_monolingual_v1",  # Or other appropriate Eleven Labs model
        "voice_settings": {
            "stability": 0.5,
            "similarity_boost": 0.75
        }
    }

    try:
        response = requests.post(
            f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
            headers=headers,
            json=data
        )
        response.raise_for_status()  # Raise an HTTPError for bad responses (4xx or 5xx)

        with open(output_filepath, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)

        return {
            "brief_text": brief_text,
            "output_filepath": output_filepath,
            "message": "Audio brief generated successfully."
        }
    except requests.exceptions.RequestException as e:
        return {"error": str(e), "message": "Failed to generate audio brief with Eleven Labs API."}
